//
// Runs a ToyAdmos program (inference, Integrated Gradients or Gradient SHAP
// of ad01_int8 on real DCASE ToyCar data) generated by data/toyadmos.py:
//  - the DMA core loads the static TCDM image, places the input vector x into
//    row 0 of its operand (2-D DMA) and streams weight / bias tiles from L3,
//    one step ahead, into two alternating parameter buffers;
//  - core 0 configures and runs one GeMMX launch per step;
//  - ReLU masks of the backward pass are applied by both cores (4 bytes per
//    word operation); core 0 gathers attribution diagonals and combines the
//    network and direct gradient terms;
//  - after every core-side op both cores synchronise, so the DMA core never
//    prefetches into a buffer that is still being read;
//  - every output region is compared byte for byte with the emulator.
// Configuration: generated straight-line writes of only the registers that
// changed since the previous launch (cfg_fns, from gemmx_sched.py); build
// with -DCFG_LIB to use the library's set_gemmx_*_csr instead.

#include <stdint.h>

#include "data.h"
#include "gemmx_exec.h"
#include "snrt.h"

enum { POST_NONE = 0, POST_MASK = 1, POST_DIAG = 2, POST_COMBINE = 3, POST_ROW = 4 };
enum { PH_BACKWARD = 3, PH_ATTR = 4, N_PHASES = 5 };

// g[i] = 0 where the ReLU of the forward activation was inactive
// (a == -128, the hidden layers' zero point). Word-wise: v = a ^ 0x80 is
// a + 128 as unsigned bytes; nonzero bytes become 0xFF in the mask.
static void relu_mask(int8_t *g, const int8_t *a, uint32_t n) {
    uint32_t *gw = (uint32_t *)g;
    const uint32_t *aw = (const uint32_t *)a;
    for (uint32_t i = 0; i < n / 4; i++) {
        uint32_t v = aw[i] ^ 0x80808080u;
        uint32_t t = (((v & 0x7F7F7F7Fu) + 0x7F7F7F7Fu) | v) & 0x80808080u;
        gw[i] &= (t << 1) - (t >> 7);
    }
}

// Diagonal gather: out[f] = element (f%8, f%8) of int32 block f/8.
static void diag_gather(const int32_t *d, int32_t *out) {
    for (int blk = 0; blk < 80; blk++)
        for (int r = 0; r < 8; r++) out[blk * 8 + r] = d[blk * 64 + r * 9];
}

// attr = m0 * attr_g0 - m1 * attr_gy (network term - direct term).
static void combine(const int32_t *a0, const int32_t *agy, int32_t *out, int32_t m0,
                    int32_t m1) {
    for (int f = 0; f < 640; f++) out[f] = m0 * a0[f] - m1 * agy[f];
}

int main() {
    uint8_t *l1 = (uint8_t *)snrt_l1_next();
    const int core0 = snrt_global_core_idx() == 0;
    const int dm = snrt_is_dm_core();

    if (dm) {
        snrt_dma_start_1d(l1, prog_image, PROG_IMAGE_BYTES);
        snrt_dma_wait_all();
    }
    snrt_cluster_hw_barrier();

    uint32_t phase_cyc[N_PHASES] = {0}, cfg = 0, run = 0, mask = 0, core_ops = 0;
    uint32_t x0 = 0, x1 = 0;
    uint32_t t_start = snrt_mcycle();
    if (dm) {
        // x (640 int8) -> row 0 of each 8x8 block of its operand.
        x0 = snrt_mcycle();
        snrt_dma_start_2d(l1 + PROG_X_DST, prog_x, 8, 64, 8, 80);
#if PROG_FIRST_BLOB >= 0
        snrt_dma_start_1d(l1 + prog_blob_dst[PROG_FIRST_BLOB],
                          prog_params + prog_blob_off[PROG_FIRST_BLOB],
                          prog_blob_len[PROG_FIRST_BLOB]);
#endif
        snrt_dma_wait_all();
        x1 = snrt_mcycle();
    }
    snrt_cluster_hw_barrier();

    for (int s = 0; s < PROG_N_STEPS; s++) {
        const step_t *st = &prog_steps[s];
        if (dm && st->prefetch >= 0)
            snrt_dma_start_1d(l1 + prog_blob_dst[st->prefetch],
                              prog_params + prog_blob_off[st->prefetch],
                              prog_blob_len[st->prefetch]);
        if (core0 && st->launch >= 0) {
            uint32_t a = snrt_mcycle();
#ifdef CFG_LIB
            gemmx_configure(&prog_launches[st->launch]);
#else
            cfg_fns[st->launch]((uint32_t)l1);
#endif
            uint32_t b = snrt_mcycle();
            gemmx_run();
            uint32_t c = snrt_mcycle();
            cfg += b - a;
            run += c - b;
            phase_cyc[st->phase] += c - a;
        }
        if (dm) snrt_dma_wait_all();
        snrt_cluster_hw_barrier();
        if (st->post == POST_NONE) continue;

        uint32_t a = snrt_mcycle();
        if (st->post == POST_MASK) {
            // Both cores mask half of the gradient each.
            uint32_t half = (st->n / 2) & ~7u;
            if (core0) relu_mask((int8_t *)(l1 + st->a), (int8_t *)(l1 + st->b), half);
            if (dm)
                relu_mask((int8_t *)(l1 + st->a + half), (int8_t *)(l1 + st->b + half),
                          st->n - half);
        } else if (core0 && st->post == POST_DIAG) {
            diag_gather((const int32_t *)(l1 + st->a), (int32_t *)(l1 + st->b));
        } else if (dm && st->post == POST_ROW) {
            // Fused inference: copy one sample's output row (8 B per block).
            snrt_dma_start_2d(l1 + st->b, l1 + st->a, 8, 8, 64, 80);
            snrt_dma_wait_all();
        } else if (core0 && st->post == POST_COMBINE) {
            combine((const int32_t *)(l1 + st->a), (const int32_t *)(l1 + st->b),
                    (int32_t *)(l1 + st->n), st->m0, st->m1);
        }
        snrt_cluster_hw_barrier();
        if (core0) {
            uint32_t c = snrt_mcycle() - a;
            if (st->post == POST_MASK) {
                mask += c;
                phase_cyc[PH_BACKWARD] += c;
            } else {
                core_ops += c;
                phase_cyc[PH_ATTR] += c;
            }
        }
    }
    uint32_t t_end = snrt_mcycle();
    snrt_cluster_hw_barrier();

    uint32_t err = 0;
    if (dm) printf("[DMA] x placement + first tile: %u cycles\n", x1 - x0);
    if (core0) {
        printf("[TOTAL] %u cycles, %d steps: config=%u run=%u mask=%u gather+combine=%u\n",
               t_end - t_start, PROG_N_STEPS, cfg, run, mask, core_ops);
        for (int p = 0; p < N_PHASES; p++)
            if (phase_cyc[p]) printf("  %-9s %u\n", prog_phase_names[p], phase_cyc[p]);
        for (int c = 0; c < PROG_N_CHECKS; c++) {
            const uint8_t *got = l1 + prog_check_off[c];
            const uint8_t *exp = prog_expected + prog_check_pos[c];
            uint32_t e = 0;
            for (int j = 0; j < prog_check_len[c]; j++) e += got[j] != exp[j];
            printf("check %-7s %s (%u/%d bytes differ)\n", prog_check_names[c],
                   e ? "FAIL" : "OK", e, prog_check_len[c]);
            err += e;
        }
    }
    snrt_cluster_hw_barrier();
    return err;
}
